// Driver: run many core-inline cases, 2 per executable invocation (slots a and c).
import { run, MK } from '/tmp/probe/p.mjs';
import { readFileSync } from 'node:fs';

function pair(s1, s2) {
  const args = { ...MK };
  args.a = s1;
  if (s2 !== undefined) args.c = s2;
  const out = run(args);
  if (out.startsWith('ERR(')) return [out, out];
  const lines = out.split('\n');
  const iB = lines.indexOf('<p>' + MK.b + '</p>');
  const iD = lines.indexOf('<p>' + MK.d + '</p>');
  if (iB < 0 || iD < 0) return ['PARSEFAIL:' + out, 'PARSEFAIL'];
  const oa = lines.slice(0, iB).join('\n');
  const oc = lines.slice(iB + 1, iD).join('\n');
  return [oa, oc];
}

const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const results = [];
for (let i = 0; i < cases.length; i += 2) {
  const s1 = cases[i], s2 = cases[i + 1];
  const [o1, o2] = pair(s1, s2);
  results.push([s1, o1]);
  if (s2 !== undefined) results.push([s2, o2]);
}
for (const [inp, outp] of results) {
  console.log(JSON.stringify(inp) + '\n  => ' + JSON.stringify(outp));
}

